def lcm_all(nums):
    """Least common multiple of a list of positive integers."""
    def gcd(a, b):
        while b:
            a, b = b, a % b
        return a

    def lcm(a, b):
        return a * b // gcd(a, b)

    out = 1
    for n in nums:
        out = lcm(out, n)
    return out
