import registry


def run(name, *args):
    """Run the plugin called `name`. Plugin names are case-insensitive."""
    # Try exact match first
    fn = registry.lookup(name)
    if fn is not None:
        return fn(*args)

    # Case-insensitive lookup: find plugin by comparing lowercased names
    for key in registry._PLUGINS:
        if key.lower() == name.lower():
            fn = registry.lookup(key)
            if fn is not None:
                return fn(*args)

    raise KeyError(f"no plugin {name!r}")
