def parse_version(text):
    """'1.2.3' -> (1, 2, 3)"""
    if text is None or not isinstance(text, str):
        return None

    text = text.strip()
    if not text:
        return None

    # Remove leading 'v' if present
    if text.startswith('v'):
        text = text[1:]
        # After removing 'v', check if there's a space (malformed like 'v 1.2.3')
        if text.startswith(' '):
            return None
        text = text.strip()

    if not text:
        return None

    parts = text.split(".")

    # Must have exactly 3 parts
    if len(parts) != 3:
        return None

    # Each part must be a valid integer
    try:
        version = tuple(int(p) for p in parts)
    except ValueError:
        return None

    return version
