from textfmt import title_word


def title_case(text):
    """Title-case a phrase for display."""
    words = text.split()
    if not words:
        return ""

    result = []
    for i, word in enumerate(words):
        if i == 0:
            # First word is always title-cased
            result.append(title_word(word, first=True))
        else:
            result.append(title_word(word, first=False))

